package com.adc.infrastructure;

import com.adc.domain.shared.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class AppointmentBookingStore {
    private final JdbcTemplate db;private final Clock clock;
    public AppointmentBookingStore(JdbcTemplate db,Clock clock){this.db=db;this.clock=clock;}
    public long bound(String subject){var rows=db.query("SELECT patient_id FROM adc_identity.CurrentPatientBinding WHERE subject_id=?",(r,n)->r.getLong(1),subject);if(rows.isEmpty())throw new DomainFailure(403,"PATIENT_BINDING_REQUIRED");return rows.getFirst();}
    public void treatments(long dentist,LocalDate date,List<Long> treatments,boolean lock){
        if(treatments==null || new HashSet<>(treatments).size()!=treatments.size())throw new DomainFailure(422,"INVALID_TREATMENT_SELECTION");
        for(long treatment:new TreeSet<>(treatments)){
            var rows=db.query("SELECT is_active FROM adc_business.Treatment WHERE treatment_id=?"+(lock?" FOR UPDATE":""),(r,n)->r.getBoolean(1),treatment);if(rows.isEmpty() || !rows.getFirst())throw new DomainFailure(422,"TREATMENT_UNAVAILABLE");
            int missing=db.queryForObject("SELECT COUNT(*) FROM adc_business.TreatmentQualification t JOIN adc_business.Qualification q ON q.qualification_id=t.qualification_id WHERE t.treatment_id=? AND t.is_mandatory=true AND (q.is_active=false OR NOT EXISTS (SELECT 1 FROM adc_business.DentistQualification d WHERE d.dentist_id=? AND d.qualification_id=t.qualification_id AND BINARY d.verification_status=BINARY 'VERIFIED' AND d.granted_date<=? AND (d.expiry_date IS NULL OR d.expiry_date>=?)))",Integer.class,treatment,dentist,date,date);if(missing>0)throw new DomainFailure(422,"DENTIST_QUALIFICATION_UNAVAILABLE");
        }
    }
    public boolean occupied(long dentist,Instant start,int minutes){return occupiedExcept(dentist,start,minutes,0);}
    public record CandidateWindow(Instant start,Instant end){public boolean overlaps(Instant at,int minutes){return start.isBefore(at.plusSeconds(minutes*60L))&&end.isAfter(at);}}
    /** Read projection for a single candidate request. Creation still locks and rechecks occupiedExcept. */
    public List<CandidateWindow> candidateWindows(long dentist,Instant start,Instant end){
        var windows=new ArrayList<>(db.query("SELECT a.scheduled_at,DATE_ADD(a.scheduled_at,INTERVAL s.slot_minutes MINUTE) ends_at FROM adc_business.Appointment a JOIN adc_business.DentistSchedule s ON s.schedule_id=a.schedule_id WHERE a.dentist_id=? AND a.status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','INVOICED') AND a.scheduled_at<? AND DATE_ADD(a.scheduled_at,INTERVAL s.slot_minutes MINUTE)>?",(r,n)->new CandidateWindow(r.getObject(1,LocalDateTime.class).toInstant(ZoneOffset.UTC),r.getObject(2,LocalDateTime.class).toInstant(ZoneOffset.UTC)),dentist,utc(end),utc(start)));
        windows.addAll(db.query("SELECT scheduled_at,DATE_ADD(scheduled_at,INTERVAL slot_minutes MINUTE) ends_at FROM adc_business.BookingHold WHERE dentist_id=? AND status='HELD' AND expires_at>? AND scheduled_at<? AND DATE_ADD(scheduled_at,INTERVAL slot_minutes MINUTE)>?",(r,n)->new CandidateWindow(r.getObject(1,LocalDateTime.class).toInstant(ZoneOffset.UTC),r.getObject(2,LocalDateTime.class).toInstant(ZoneOffset.UTC)),dentist,utc(clock.instant()),utc(end),utc(start)));
        return windows;
    }
    public boolean occupiedExcept(long dentist,Instant start,int minutes,long excludedHold){return db.queryForObject("SELECT COUNT(*) FROM adc_business.Appointment a JOIN adc_business.DentistSchedule s ON s.schedule_id=a.schedule_id WHERE a.dentist_id=? AND a.status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','INVOICED') AND a.scheduled_at<? AND DATE_ADD(a.scheduled_at,INTERVAL s.slot_minutes MINUTE)>?",Integer.class,dentist,utc(start.plusSeconds(minutes*60L)),utc(start))>0 || db.queryForObject("SELECT COUNT(*) FROM adc_business.BookingHold WHERE dentist_id=? AND hold_id<>? AND status='HELD' AND expires_at>? AND scheduled_at<? AND DATE_ADD(scheduled_at,INTERVAL slot_minutes MINUTE)>?",Integer.class,dentist,excludedHold,utc(clock.instant()),utc(start.plusSeconds(minutes*60L)),utc(start))>0;}
    private static LocalDateTime utc(Instant value){return LocalDateTime.ofInstant(value,ZoneOffset.UTC);}
    public boolean hasActiveHold(long dentist,Instant start,int minutes){return db.queryForObject("SELECT COUNT(*) FROM adc_business.BookingHold WHERE dentist_id=? AND status='HELD' AND expires_at>? AND scheduled_at<? AND DATE_ADD(scheduled_at,INTERVAL slot_minutes MINUTE)>?",Integer.class,dentist,utc(clock.instant()),utc(start.plusSeconds(minutes*60L)),utc(start))>0;}
    public long create(long patient,ScheduleStore.Schedule schedule,Instant at,List<Long> treatments,String role,String actor,String key){long id=Crypto.id();db.update("INSERT INTO adc_business.Appointment (appointment_id,patient_id,clinic_id,dentist_id,schedule_id,scheduled_at,status,created_at,updated_at) VALUES (?,?,?,?,?,?,'SCHEDULED',?,?)",id,patient,schedule.clinic(),schedule.dentist(),schedule.id(),utc(at),utc(clock.instant()),utc(clock.instant()));for(long treatment:treatments)db.update("INSERT INTO adc_business.AppointmentRequestedTreatment VALUES (?,?,NULL)",id,treatment);db.update("INSERT INTO adc_business.AppointmentEvent VALUES (?,?,'BOOK',NULL,'SCHEDULED',?,?,?,NULL,?,NULL)",Crypto.id(),id,utc(clock.instant()),role,actor,key);return id;}
    public Map<String,Object> view(long id){var rows=db.query("SELECT a.appointment_id,a.patient_id,a.clinic_id,a.dentist_id,a.schedule_id,a.scheduled_at,a.status,a.attended_at,a.completed_at,a.cancellation_kind,a.rescheduled_from_id,i.invoice_id,p.full_name,p.patient_number,d.full_name,c.clinic_code clinic_name FROM adc_business.Appointment a JOIN adc_business.Patient p ON p.patient_id=a.patient_id JOIN adc_business.Dentist d ON d.dentist_id=a.dentist_id JOIN adc_business.Clinic c ON c.clinic_id=a.clinic_id LEFT JOIN adc_business.Invoice i ON i.appointment_id=a.appointment_id WHERE a.appointment_id=?",(r,n)->{var view=new LinkedHashMap<String,Object>();for(int i=1;i<=5;i++)view.put(new String[]{"appointment_id","patient_id","clinic_id","dentist_id","schedule_id"}[i-1],r.getString(i));view.put("scheduled_at",r.getObject(6,LocalDateTime.class).toInstant(ZoneOffset.UTC).toString());view.put("status",r.getString(7));for(int i=8;i<=9;i++){var time=r.getObject(i,LocalDateTime.class);view.put(i==8?"attended_at":"completed_at",time==null?null:time.toInstant(ZoneOffset.UTC).toString());}view.put("cancellation_kind",r.getString(10));view.put("rescheduled_from_id",r.getString(11));view.put("invoice_id",r.getString(12));view.put("patient_name",r.getString(13));view.put("patient_number",r.getString(14));view.put("dentist_name",r.getString(15));view.put("clinic_name",r.getString(16));return (Map<String,Object>)view;},id);if(rows.isEmpty())throw new DomainFailure(404,"OBJECT_NOT_ACCESSIBLE");return rows.getFirst();}
    public long registrationFee(long clinic,long dentist){var rows=db.query("SELECT amount_fen FROM adc_business.RegistrationFeePolicy WHERE clinic_id=? AND dentist_id=?",(r,n)->r.getLong(1),clinic,dentist);return rows.isEmpty()?0:rows.getFirst();}
    public Map<String,Object> doctorProfile(long dentist){return db.queryForObject("SELECT full_name,professional_title,specialty,introduction FROM adc_business.Dentist WHERE dentist_id=?",(r,n)->{var p=new LinkedHashMap<String,Object>();p.put("dentist_name",r.getString(1));p.put("professional_title",r.getString(2));p.put("specialty",r.getString(3));p.put("introduction",r.getString(4));return p;},dentist);}
    public String dentistName(long dentist){return db.queryForObject("SELECT full_name FROM adc_business.Dentist WHERE dentist_id=?",String.class,dentist);}
    public List<Map<String,Object>> list(Long patient,List<Long> clinics,Instant start,Instant end,String status,long after,int limit){var args=new ArrayList<Object>();String where="appointment_id>?";args.add(after);if(patient!=null){where+=" AND patient_id=?";args.add(patient);}if(clinics!=null){where+=" AND clinic_id IN ("+String.join(",",Collections.nCopies(clinics.size(),"?"))+")";args.addAll(clinics);}if(start!=null){where+=" AND scheduled_at>=?";args.add(utc(start));}if(end!=null){where+=" AND scheduled_at<?";args.add(utc(end));}if(status!=null){where+=" AND status=?";args.add(status);}args.add(limit);return db.query("SELECT appointment_id FROM adc_business.Appointment WHERE "+where+" ORDER BY appointment_id LIMIT ?",(r,n)->r.getLong(1),args.toArray()).stream().map(this::view).toList();}
}
